#include <cstdio>

#include <cfloat>

using namespace std;



char food[10][21];

int num, weight[10], speed[10], ans[10], seq[10];

bool used[10];

float maxGain;



void depthFirstSearch(int idx, int totalWeight, int m, float gain) {

  if (m == num) {

    if (maxGain < gain) {

      maxGain = gain;

      for (int i=0; i<num; i++) {

        seq[i] = ans[i];

      }

    }

    return;

  }

  if (idx>=num) {

    return;

  }

  if (!used[idx] && totalWeight <= speed[idx]) {

    used[idx] = true;

    totalWeight += weight[idx];

    ans[m] = idx;

    depthFirstSearch(0, totalWeight, m+1, gain + weight[idx]*(m+1));

    totalWeight -= weight[idx];

    used[idx] = false;

  }

  depthFirstSearch(idx+1, totalWeight, m, gain);

}



int main() {

  while (1) {

    scanf("%d", &num);

    if (!num) break;

    for (int i=0; i<num; i++) {

      scanf("%s %d %d", food[i], &weight[i], &speed[i]);

    }

    for (int i=0; i<num; i++) {

      used[i] = false;

    }

    maxGain = -DBL_MAX;

    depthFirstSearch(0, 0, 0, 0.);

    for (int i=num-1; i>=0; i--) {

      printf("%s\n", food[seq[i]]);

    }

  }

  return 0;

}

