#include <cfloat>

using namespace std;

char f[10][21];

int n, w[10], s[10], a[10], b[10];

bool u[10];

double maxg;

// Backtracking DFS to explore all valid combinations

void dfs(int x, int tw, int m, double g) {

  if (m == n) {

    if (maxg < g) {

      maxg = g;

      for (int i=0; i<n; i++) {

        b[i] = a[i]; // Save the best combination found

      }

    }

    return;

  }

  if (x>=n) {

    return; // End of recursion

  }

  if (!u[x] && tw <= s[x]) { // Check if the current item can be used

    u[x] = true;

    tw += w[x];

    a[m] = x;

    dfs(0, tw, m+1, g + w[x]*(m+1)); // Recur with the updated state

    tw -= w[x];

    u[x] = false;

  }

  dfs(x+1, tw, m, g); // Move to the next item

}



int main() {

  while (1) {

    scanf("%d", &n); // Number of items

    if (!n) break; // Termination condition

    for (int i=0; i<n; i++) {

      scanf("%s %d %d", f[i], &w[i], &s[i]); // Read item data

    }

    for (int i=0; i<n; i++) {

      u[i] = false; // Reset usage state

    }

    maxg = -DBL_MAX; // Initialize maximum gain

    dfs(0, 0, 0, 0.); // Start DFS

    for (int i=n-1; i>=0; i--) {

      printf("%s\n", f[b[i]]); // Output the best combination in reverse order

    }

  }

  return 0;

}

